SELECT m.id, m.symbol, m.observed_at, m.created_at, UNIX_TIMESTAMP(m.created_at) AS epoch_s, ROUND(TIMESTAMPDIFF(MICROSECOND, m.observed_at, m.created_at)/1000) AS lag_ms, m.delivery_status FROM crypto_ai.market_price_event m WHERE m.source='BINANCE_KLINE_DIRECT_FIX153' AND m.created_at BETWEEN '2026-10-11 22:00:00' AND '2026-10-11 23:00:00' AND TIMESTAMPDIFF(MICROSECOND, m.observed_at, m.created_at) > 5000000 ORDER BY m.created_at LIMIT 100